// Replaces the vendored database types with a freshly generated file from the DHA-Works-Platform repository.
//   npm run types:sync -- ../DHA-Works-Platform/packages/supabase/database.types.ts
// The file is generated by `supabase gen types typescript --linked`; it is never edited by hand.
import { copyFileSync, readFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const source = process.argv[2];
if (!source) {
  console.error('Usage: npm run types:sync -- <path to database.types.ts>');
  process.exit(1);
}
const text = readFileSync(resolve(source), 'utf8');
// A cheap sanity check, so a wrong file is not copied over the types by mistake.
if (!text.startsWith('export type Json') || !text.includes('admin_session_status') || !text.includes('public: {')) {
  console.error('That does not look like the generated DHA Works database types (missing Json, public schema or admin_session_status).');
  process.exit(1);
}
const target = join(dirname(fileURLToPath(import.meta.url)), '..', 'vendor', 'supabase', 'database.types.ts');
copyFileSync(resolve(source), target);
console.log(`Copied ${resolve(source)} to ${target}. Run typecheck, then commit it.`);
